<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { app, gs, stage, selectToken, game, endTurn, aimToken } from '../session'
import Portrait from './Portrait.vue'
const list = computed(() => { const G = gs.value, c = G?.combat; if (!c) return []; return c.order.map((t, i) => ({ ...t, i, h: G.chars[t.id], m: G.mons[t.id] })).filter(t => (t.h && !t.h.dead) || (t.m && t.m.hp > 0 && t.m.state !== 'fled' && (app.role === 'dm' || !app.tokens.find(k => k.id === t.id)?.hidden))) }); const cur = computed(() => gs.value?.combat?.i ?? -1); const mine = computed(() => { const c = gs.value?.combat; return !!c && c.order[c.i]?.id === app.seat }); const root = ref<HTMLElement>(); watch(cur, () => nextTick(() => root.value?.querySelector('.on')?.scrollIntoView({ block: 'nearest', inline: 'center', behavior: 'smooth' }))); const see = (id: string) => { if (app.aim) { aimToken(id); return } selectToken(id); const t = app.tokens.find(k => k.id === id), g = game.value; if (t && g?.view.flat) g.centerOn(t.x, t.z, g.nav.levelOf(t.x, t.y, t.z)) }
const pct = (t: any) => t.h ? t.h.hp / Math.max(1, app.tokens.find(k => k.id === t.id)?.max ?? t.h.hp) : t.m.hp / t.m.max
</script>
<template><div v-if="gs?.combat" class="rb"><div class="rd" :class="{ mine }"><small>Round {{ gs.combat.round }}</small><b class="cut">{{ mine ? 'Your turn' : list.find(t => t.i === cur)?.h?.name ?? list.find(t => t.i === cur)?.m?.name ?? '' }}</b></div><div ref="root" class="tr"><button v-for="t in list" :key="t.id" :class="{ on: t.i === cur, down: t.h && t.h.hp <= 0 }" v-tip="(t.h?.name ?? t.m!.name) + ', initiative ' + t.init" @click="see(t.id)"><Portrait :hero="t.h" :mon="t.m" :model="t.m?.npc && !t.m.npc.as ? app.tokens.find(k => k.id === t.id)?.m : undefined" :id="t.id" :size="50" /><span class="hp" :class="{ hero: t.h }"><i :style="{ width: Math.max(0, Math.min(1, pct(t))) * 100 + '%' }" /></span><em>{{ t.init }}</em></button></div><template v-if="app.role === 'dm'"><button class="btn" v-tip="['End this turn', 'Space']" @click="endTurn()">Next</button><button class="btn quiet" @click="stage?.endFight()">End fight</button></template></div></template>
<style scoped>.rb{display:flex;align-items:stretch;pointer-events:auto;background:var(--navy);max-width:100%;min-width:0}.rd{padding:8px 16px;min-width:120px;max-width:190px;display:grid;align-content:center}.rd small{display:block;font-size:14.5px;line-height:1;color:var(--tx2)}.rd b{font:700 22px/1.05 var(--serif)}.rd.mine{background:var(--spot);color:var(--on-spot)}.rd.mine small{color:inherit}.tr{display:flex;overflow-x:auto;scrollbar-width:none;min-width:0}.tr button{position:relative;flex:none;width:50px;opacity:.72}.tr .on{opacity:1;outline:4px solid var(--spot);outline-offset:-4px}.tr button:hover{opacity:1}.tr .down{filter:grayscale(1)}.tr .hp{height:6px;display:block}.tr em{font:600 14px/17px var(--ui);font-style:normal;text-align:center;display:block;color:var(--tx2)}.btn{height:auto;align-self:stretch}@media(max-width:899px){.rb{width:100%}.rd{min-width:92px;max-width:110px;padding:4px 10px}.rd b{font-size:18px}.tr{flex:1}}</style>
